import uuid, random; from sqlalchemy import select; from app.core.database import SessionLocal; from app.models.procurement import Bill, BillStatus, WorkOrder; db = SessionLocal(); wos = db.execute(select(WorkOrder)).scalars().all(); bills = [Bill(id=uuid.uuid4(), work_order_id=w.id, contractor_id=w.contractor_id, amount=random.uniform(50000, 500000), status=random.choice([BillStatus.SUBMITTED, BillStatus.APPROVED, BillStatus.REJECTED])) for w in wos[:5]]; db.add_all(bills); db.commit(); print('Patched'); db.close()
